+	switch (ribbon_mode) {
+		case Ribbon::RibbonMode::RIBBON_MODE_BEAM: {
+			if (p_property.name == "points") {
+				p_property.usage = PROPERTY_USAGE_NONE;
+			} else if (p_property.name == "normals") {
+				p_property.usage = PROPERTY_USAGE_NONE;
+			} else if (p_property.name == "lifetime") {
+				p_property.usage = PROPERTY_USAGE_NONE;
+			} else if (p_property.name == "max_length") {
+				p_property.usage = PROPERTY_USAGE_NONE;
