+shader_type spatial;
+render_mode
+	blend_add,
+	depth_draw_never,
+	unshaded,
+	skip_vertex_transform,
+	cull_disabled;
+
+void vertex() {
+	vec3 p = (MODELVIEW_MATRIX * vec4(VERTEX, 1.0)).xyz;
+	vec3 t = (MODELVIEW_MATRIX * vec4(NORMAL, 0.0)).xyz;
+	VERTEX = p + UV.y * normalize(cross(p, t));
+	NORMAL = (VIEW_MATRIX * vec4(0, 1, 0, 0)).xyz;
+	UV.y = (sign(UV.y) + 1.0) / 2.0;
+}
+
+void fragment() {
+	ALBEDO = COLOR.rgb;
+	ALPHA = COLOR.a;
+}
+)");
+	billboard_shader.instantiate();
+	billboard_shader->set_code(R"(
+shader_type spatial;
+render_mode
+	blend_mix,
+	depth_draw_never,
+	unshaded,
+	skip_vertex_transform,
+	cull_disabled;
+
+void vertex() {
+	vec3 p = (MODELVIEW_MATRIX * vec4(VERTEX, 1.0)).xyz;
+	vec3 t = (MODELVIEW_MATRIX * vec4(NORMAL, 0.0)).xyz;
+	VERTEX = p + UV.y * normalize(cross(p, t));
+	NORMAL = (VIEW_MATRIX * vec4(0, 1, 0, 0)).xyz;
+	UV.y = (sign(UV.y) + 1.0) / 2.0;
+}
+
+void fragment() {
+	ALBEDO = COLOR.rgb;
+	ALPHA = COLOR.a;
+}
+)");
+	local_additive_shader.instantiate();
+	local_additive_shader->set_code(R"(
+shader_type spatial;
+render_mode
+	blend_add,
+	depth_draw_never,
+	unshaded,
+	cull_disabled;
+
+void fragment() {
+	ALBEDO = COLOR.rgb;
+	ALPHA = COLOR.a;
+}
+)");
+	local_shader.instantiate();
+	local_shader->set_code(R"(
+shader_type spatial;
+render_mode
+	blend_mix,
+	depth_draw_never,
+	unshaded,
+	cull_disabled;
+
+void fragment() {
+	ALBEDO = COLOR.rgb;
+	ALPHA = COLOR.a;
+}
+)");
