+void Ribbon::_do_rebuild() {
+	if (!is_inside_tree() || !is_ready() || !_needs_rebuilding) {
+		return;
+	}
+	if (mesh == nullptr || (Ref<ArrayMesh>)mesh == nullptr) {
+		mesh = new ArrayMesh();
+	}
+	Ref<ArrayMesh> am = (Ref<ArrayMesh>)mesh;
+	am->clear_surfaces();
+
+	int points_count = points.size();
+	int start_idx = 0;
+
+	while (points_count >= 2 && points[start_idx + 1].is_equal_approx(points[start_idx])) {
+		start_idx += 1;
+		points_count -= 1;
+	}
+	while (points_count >= 2 and points[start_idx + points_count - 1].is_equal_approx(points[start_idx + points_count - 2])) {
