+		int j = i * 12;
+		int k = i * 3;
+		_indices[j] = k;
+		_indices[j + 1] = k + 3;
+		_indices[j + 2] = k + 1;
+		_indices[j + 3] = k + 1;
+		_indices[j + 4] = k + 3;
+		_indices[j + 5] = k + 4;
+		_indices[j + 6] = k + 1;
+		_indices[j + 7] = k + 4;
+		_indices[j + 8] = k + 2;
+		_indices[j + 9] = k + 2;
+		_indices[j + 10] = k + 4;
+		_indices[j + 11] = k + 5;
+	}
+
+	Transform3D inv_global_tf = get_global_transform().inverse();
+
+	real_t length = _calc_current_length();
+
+	real_t dist = 0.0;
+
+	for (int i = 0; i < points_count; i++) {
+		int j0 = i * 3;
+		int j1 = j0 + 1;
+		int j2 = j0 + 2;
+
+		Vector3 p = points[i + start_idx];
+
+		if (i > 0) {
+			dist += points[i - 1 + start_idx].distance_to(p);
+		}
+
+		real_t ratio = length > 0.0 ? dist / length : 0.0;
