+				}
+			} break;
+			case Ribbon::Tiling::TLING_UNIT: {
+				length_uv = ratio * tiling_multiplier;
+			} break;
+			default: {
+			}
+		}
+
+		real_t half_width = width * 0.5;
+
+		if (width_curve.is_valid()) {
+			half_width *= width_curve->sample(ratio);
+		}
