+void Ribbon::_notification(int p_what) {
+	switch (p_what) {
+		case NOTIFICATION_INTERNAL_PROCESS: {
+			switch (ribbon_mode) {
+				case Ribbon::RIBBON_MODE_TRAIL: {
+					_process_trail(get_process_delta_time());
+				} break;
+			}
+			if (_needs_rebuilding) {
+				_do_rebuild();
+			}
+		} break;
+	}
+}
