+	if (p_property.name == "max_length" && limit_mode == LIMIT_MODE_LIFETIME) {
+		p_property.usage = PROPERTY_USAGE_NONE;
+	}
+	switch (ribbon_mode) {
+		case RIBBON_MODE_BEAM: {
+			if (p_property.name == "points") {
+				p_property.usage = PROPERTY_USAGE_NONE;
+			} else if (p_property.name == "normals") {
