+void Trail3D::_ensure_material() {
+	if (!mesh.is_valid()) {
+		return;
+	}
+	switch (material_mode) {
+		case Trail3D::MaterialMode::MATERIAL_MODE_ADD: {
+			if (alignment == MeshAlignment::MESH_ALIGNMENT_BILLBOARD) {
+				mesh->surface_set_material(0, billboard_additive_material);
+			} else {
+				mesh->surface_set_material(0, local_additive_material);
+			}
+
+		} break;
+		case Trail3D::MaterialMode::MATERIAL_MODE_MIX: {
+			if (alignment == MeshAlignment::MESH_ALIGNMENT_BILLBOARD) {
+				mesh->surface_set_material(0, billboard_material);
+			} else {
+				mesh->surface_set_material(0, local_material);
+			}
+		} break;
+		case Trail3D::MaterialMode::MATERIAL_MODE_CUSTOM: {
+			mesh->surface_set_material(0, material);
+		} break;
+		case Trail3D::MaterialMode::MATERIAL_MODE_MAX: {
+		} break;
