+void Trail3D::_notification(int p_what) {
+	switch (p_what) {
+		case NOTIFICATION_INTERNAL_PROCESS: {
+			_process_trail(get_process_delta_time());
+			if (_needs_rebuilding) {
+				_do_rebuild();
+			}
+		} break;
+		case NOTIFICATION_READY: {
+			clear();
+		}
+	}
